// Capability probe only: exact native cuBLASLt descriptor contract, no matrix computation or timing claimed.
#define main original_hecbench_main
#include "../blas-fp8gemm-cuda/main.cu"
#undef main
int main(){cudaDeviceProp prop;cudaGetDeviceProperties(&prop,0);printf("GPU %s sm%d%d cuBLASLt_version=%zu\n",prop.name,prop.major,prop.minor,cublasLtGetVersion());cublasLtHandle_t h;auto create=cublasLtCreate(&h);if(create){printf("create_status=%d\n",create);return 2;}float*scale;cudaMalloc(&scale,4);float one=1;cudaMemcpy(scale,&one,4,cudaMemcpyHostToDevice);
const int dims[7][3]={{64,64,64},{16384,8192,1280},{16384,1024,8192},{16384,8192,7168},{16384,3584,8192},{8192,8192,8192},{16384,16384,16384}};
for(auto&shape:dims){int m=shape[0],n=shape[1],k=shape[2];cublasLtMatmulDesc_t op;checkCublasStatus(cublasLtMatmulDescCreate(&op,CUBLAS_COMPUTE_32F,CUDA_R_32F));cublasOperation_t ta=CUBLAS_OP_T,tb=CUBLAS_OP_N;checkCublasStatus(cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_TRANSA,&ta,sizeof(ta)));checkCublasStatus(cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_TRANSB,&tb,sizeof(tb)));checkCublasStatus(cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_A_SCALE_POINTER,&scale,sizeof(scale)));checkCublasStatus(cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_B_SCALE_POINTER,&scale,sizeof(scale)));int8_t fast=1;checkCublasStatus(cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_FAST_ACCUM,&fast,sizeof(fast)));
cublasLtMatrixLayout_t A,B,C,D;checkCublasStatus(cublasLtMatrixLayoutCreate(&A,CUDA_R_8F_E4M3,k,m,k));checkCublasStatus(cublasLtMatrixLayoutCreate(&B,CUDA_R_8F_E4M3,k,n,k));checkCublasStatus(cublasLtMatrixLayoutCreate(&C,CUDA_R_16BF,m,n,m));checkCublasStatus(cublasLtMatrixLayoutCreate(&D,CUDA_R_16BF,m,n,m));cublasLtMatmulPreference_t pref;checkCublasStatus(cublasLtMatmulPreferenceCreate(&pref));size_t workspace=4*1024*1024;checkCublasStatus(cublasLtMatmulPreferenceSetAttribute(pref,CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,&workspace,sizeof(workspace)));cublasLtMatmulHeuristicResult_t result={};int returned=-1;auto status=cublasLtMatmulAlgoGetHeuristic(h,op,A,B,C,D,pref,1,&result,&returned);printf("CAPABILITY_CASE m=%d n=%d k=%d heuristic_status=%d returned_algorithms=%d\n",m,n,k,status,returned);cublasLtMatmulPreferenceDestroy(pref);cublasLtMatrixLayoutDestroy(A);cublasLtMatrixLayoutDestroy(B);cublasLtMatrixLayoutDestroy(C);cublasLtMatrixLayoutDestroy(D);cublasLtMatmulDescDestroy(op);
}cudaFree(scale);cublasLtDestroy(h);return 0;}
